	var canvas = document.getElementById('pendulumCanvas');
	var ctx = canvas.getContext('2d');
	var pendulum;
	var gravity = 9.81;
	var dt = 0.01;

	function Pendulum(a0) {
		this.angle = a0;
		this.velocity = 0;
	}

	Pendulum.prototype.update = function() {
		var acceleration = -gravity / 10 * Math.sin(this.angle);
		this.velocity += acceleration * dt;
		this.angle += this.velocity * dt;
	}

	Pendulum.prototype.draw = function() {
		ctx.clearRect(0, 0, canvas.width, canvas.height);
		ctx.beginPath();
		ctx.arc(canvas.width / 2, canvas.height / 2 - 100, 100, -Math.PI / 2 + this.angle, Math.PI / 2);
		ctx.fillStyle = 'black';
		ctx.fill();
		ctx.arc(canvas.width / 2, canvas.height / 2, 4, 0, 2 * Math.PI);
		ctx.fillStyle = 'black';
		ctx.fill();
	}

	function animate() {
		if (pendulum) {
			pendulum.update();
			pendulum.draw();
		.requestAnimationFrame(animate);
		}
	}

	document.getElementById('releasePendulum').addEventListener('click', function() {
		pendulum = new Pendulum(parseInt(document.getElementById('initialAngle').value) * Math.PI / 180);
		animate();
	});

	animate();
</script>
</html>
```

